class Solution:
    def cyclicShift(self, n: int, grid: list[list[int]], rowShift: list[int], colShift: list[int]) -> list[list[int]]:
        shifted = [[row[(j + rowShift[i]) % n] for j in range(n)] for i, row in enumerate(grid)]
        return [[shifted[(i + colShift[j]) % n][j] for j in range(n)] for i in range(n)]

